const SOURCE = `import { Hono } from "hono";
import { z } from "zod";
import * as store from "../db/notes";

const PAGE_SIZE = 20;

const Tag = z.string().trim().toLowerCase();
const NoteInput = z.object({
  title: z.string().trim().min(1).max(120),
  body: z.string().default(""),
  tags: z.array(Tag).max(10).default([]),
});

export const notes = new Hono();

// Newest first, PAGE_SIZE notes per page.
notes.get("/", (c) => {
  const { before, tag } = c.req.query();
  const rows = store.list({
    before: before ? Number(before) : undefined,
    limit: PAGE_SIZE,
  });
  const page = rows.filter(
    (note) => !tag || note.tags.includes(tag),
  );
  const next = page.at(PAGE_SIZE - 1)?.id;
  return c.json({ notes: page, next });
});

notes.get("/:id", (c) => {
  const note = store.get(Number(c.req.param("id")));
  return note ? c.json(note) : c.notFound();
});

notes.post("/", async (c) => {
  const input = NoteInput.parse(await c.req.json());
  return c.json(store.create(input), 201);
});

notes.patch("/:id", async (c) => {
  const id = Number(c.req.param("id"));
  const body = await c.req.json();
  const patch = NoteInput.partial().parse(body);
  const note = store.update(id, patch);
  return note ? c.json(note) : c.notFound();
});

notes.delete("/:id", (c) => {
  const id = Number(c.req.param("id"));
  if (!store.remove(id)) return c.notFound();
  return c.body(null, 204);
});`;

const LINES = SOURCE.split("\n");

/** The selection, 1-based: the whole list route, from its first column to the end of `});` (the head). */
const SELECTION = { from: 17, to: 28 };

/** Lines the fold gutter marks: a block or an object literal that ends on a later line. */
const FOLDABLE = new Set([8, 17, 19, 30, 35, 40, 48]);

// CodeMirror's line height: the app's 12.5px editor font at the base theme's 1.4.
const LINE_HEIGHT = 17.5;
// .cm-content's top padding, which the gutters line up with.
const CONTENT_TOP = 4;

/* ------------------------------------------------------------ highlighting -- */

// GitHub Dark's colour groups for the TypeScript grammar's tags (editor-scene.css):
// keywords and types, brackets and comments, properties and classes,
// variables, numbers and operators, strings. Separators, `=>`, `?.` and null
// keep the editor's foreground.
type Tone = "k" | "c" | "p" | "v" | "s" | "";

const KEYWORDS = new Set(["import", "from", "export", "const", "new", "async", "await", "return", "if", "as"]);
const TOKEN = /\/\/.*|"(?:[^"\\]|\\.)*"|\d[\d_]*|[A-Za-z_$][\w$]*|\?\.|=>|\?\?|\|\||[=!<>+\-*/?:]|[()[\]{}]|[.,;]|\s+|./g;

/** Highlights one line of SOURCE the way the editor's TypeScript grammar tags it. */
function highlight(line: string): { tone: Tone; text: string }[] {
  const tokens: { tone: Tone; text: string }[] = [];
  let prev = "";
  let prevTone: Tone = "";
  for (const match of line.matchAll(TOKEN)) {
    const text = match[0];
    const rest = line.slice((match.index ?? 0) + text.length);
    let tone: Tone = "";
    if (/^\s+$/.test(text)) {
      tokens.push({ tone, text });
      continue;
    }
    if (text.startsWith("//")) tone = "c";
    else if (text.startsWith('"')) tone = "s";
    else if (/^\d/.test(text)) tone = "v";
    else if (/^[A-Za-z_$]/.test(text)) {
      if (KEYWORDS.has(text)) tone = "k";
      else if (text === "null") tone = "";
      // A member, a class after `new`, an object key, or a shorthand property
      // in an object literal (not in a destructuring pattern).
      else if (prev === "." || prev === "?." || prev === "new") tone = "p";
      else if ((prev === "" || prev === "{" || prev === ",") && /^\s*:/.test(rest)) tone = "p";
      else if (prev === "," && /^\s*\}\s*[^=\s]/.test(rest)) tone = "p";
      else tone = "v";
    } else if (/^[()[\]{}]$/.test(text)) tone = "c";
    else if (text === "*" && prev === "import") tone = "k";
    else if (text === ":") tone = prevTone === "p" ? "" : "v";
    else if (text === "=>" || text === "?." || text === "," || text === ";") tone = "";
    else tone = "v";
    tokens.push({ tone, text });
    prev = text;
    prevTone = tone;
  }
  return tokens;
}

/* --------------------------------------------------------- measured layout -- */

interface Rect {
  left: number;
  top: number;
  width: number;
  height: number;
}

interface SelectionLayout {
  /** The selection's pieces: its first line, the lines between, its last line. */
  pieces: Rect[];
  cursor: Rect;
  /** Where the action bar sits: under the head, in .cm-editor's box. */
  bar: { left: number; top: number };
}

/**
 * What CodeMirror's drawSelection and tooltip measure for the selection, in
 * the scroller's layout pixels: pieces run from the content's left padding
 * to its right edge, and the bar and cursor sit at the head's character box.
 */
function useSelectionLayout(scroller: RefObject<HTMLDivElement>): SelectionLayout | null {
  const [layout, setLayout] = useState<SelectionLayout | null>(null);
  useLayoutEffect(() => {
    const element = scroller.current;
    if (!element) return;
    let alive = true;
    const measure = () => {
      if (!alive) return;
      const content = element.querySelector<HTMLElement>(".cm-content");
      const lines = element.querySelectorAll<HTMLElement>(".cm-content > .cm-line");
      const first = lines[SELECTION.from - 1];
      const last = lines[SELECTION.to - 1];
      if (!content || !first || !last || last.offsetWidth === 0) return;
      const padding = getComputedStyle(first);
      const left = content.offsetLeft + parseFloat(padding.paddingLeft);
      const right = content.offsetLeft + content.offsetWidth - parseFloat(padding.paddingRight);
      // The head's character box, from the rendered text: the scene is scaled
      // to its card, so screen pixels are turned back into layout pixels.
      const lineBox = last.getBoundingClientRect();
      const scale = lineBox.width / last.offsetWidth || 1;
      const range = document.createRange();
      range.selectNodeContents(last);
      const text = range.getBoundingClientRect();
      const head = last.offsetLeft + (text.right - lineBox.left) / scale;
      const charTop = last.offsetTop + (text.top - lineBox.top) / scale;
      const charBottom = last.offsetTop + (text.bottom - lineBox.top) / scale;
      const second = lines[SELECTION.from];
      const beforeLast = lines[SELECTION.to - 2];
      setLayout({
        pieces: [
          { left, top: first.offsetTop, width: right - left, height: first.offsetHeight },
          { left, top: second.offsetTop, width: right - left, height: beforeLast.offsetTop + beforeLast.offsetHeight - second.offsetTop },
          { left, top: last.offsetTop, width: head - left, height: last.offsetHeight },
        ],
        cursor: { left: head, top: charTop, width: 0, height: Math.max(5, charBottom - charTop) },
        bar: { left: element.offsetLeft + head, top: element.offsetTop + charBottom },
      });
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    void document.fonts?.ready.then(measure);
    return () => {
      alive = false;
      observer.disconnect();
    };
  }, [scroller]);
  return layout;
}

/* ------------------------------------------------------------------ editor -- */

/** A gutter's markers as CodeMirror places them: one element per marked line, spaced by margin. */
function GutterElements({ lines, render }: { lines: number[]; render: (line: number) => ReactNode }) {
  let bottom = 0;
  return lines.map((line) => {
    const top = CONTENT_TOP + (line - 1) * LINE_HEIGHT;
    const style: CSSProperties = { height: LINE_HEIGHT, marginTop: top - bottom || undefined };
    bottom = top + LINE_HEIGHT;
    return (
      <div key={line} className={`cm-gutterElement ${line === SELECTION.to ? "cm-activeLineGutter" : ""}`} style={style}>
        {render(line)}
      </div>
    );
  });
}

const hidden: CSSProperties = { height: 0, visibility: "hidden", pointerEvents: "none" };

/** Explain, Fix and Send to agent for a tile whose terminal runs a coding agent (selectionActions.ts). */
const SELECTION_ACTIONS = [
  { label: "Explain", hint: "Ask the agent in this tile to explain the selected code" },
  { label: "Fix", hint: "Ask the agent in this tile to fix the selected code" },
  { label: "Send to agent", hint: "Send to agent (⌘L)\nPastes the code into the agent's input without sending it, so you can add your question" },
];

/** CodeMirror's DOM for the open file (@uiw/react-codemirror with the app's extensions). */
function CodeEditor() {
  const scroller = useRef<HTMLDivElement>(null);
  const layout = useSelectionLayout(scroller);
  const numbers = LINES.map((_, i) => i + 1);
  const folds = numbers.filter((line) => FOLDABLE.has(line) || line === SELECTION.to);
  return (
    <div className="cm-theme" style={{ height: "100%" }}>
      <div className="cm-editor cm-focused cm-pz-git-repo">
        <div ref={scroller} className="cm-scroller">
          <div className="cm-gutters cm-gutters-before" aria-hidden="true">
            <div className="cm-gutter cm-lineNumbers">
              <div className="cm-gutterElement" style={hidden}>
                99
              </div>
              <GutterElements lines={numbers} render={(line) => line} />
            </div>
            <div className="cm-gutter cm-foldGutter">
              <div className="cm-gutterElement" style={hidden}>
                <span title="Unfold line">›</span>
              </div>
              <GutterElements lines={folds} render={(line) => (FOLDABLE.has(line) ? <span title="Fold line">⌄</span> : null)} />
            </div>
            {/* The file is unchanged since HEAD: the column is there (a repository file) with no marks. */}
            <div className="cm-gutter cm-pz-git-gutter">
              <GutterElements lines={[SELECTION.to]} render={() => null} />
            </div>
          </div>
          <div className="cm-content" role="textbox" aria-multiline="true" data-language="typescript" style={{ tabSize: 4 }}>
            {LINES.map((line, i) => (
              <div key={i} className={`cm-line ${i + 1 === SELECTION.to ? "cm-activeLine" : ""}`}>
                {line
                  ? highlight(line).map((token, j) => (token.tone ? <span key={j} className={`es-${token.tone}`}>{token.text}</span> : token.text))
                  : <br />}
              </div>
            ))}
          </div>
          <div className="cm-layer cm-layer-above cm-cursorLayer" aria-hidden="true" style={{ zIndex: 150, animationDuration: "1200ms" }}>
            {layout ? <div className="cm-cursor cm-cursor-primary" style={{ left: layout.cursor.left, top: layout.cursor.top, height: layout.cursor.height }} /> : null}
          </div>
          <div className="cm-selectionLayer cm-layer" aria-hidden="true" style={{ zIndex: -2 }}>
            {layout?.pieces.map((piece, i) => <div key={i} className="cm-selectionBackground" style={piece} />)}
          </div>
        </div>
        {/* The selection bar, a CodeMirror tooltip below the head. CodeMirror
            positions it fixed against the viewport; in the scene's scaled
            stage it is placed in the editor's own box at the same spot. */}
        {layout ? (
          <div
            className="cm-pz-selbar cm-tooltip cm-tooltip-below"
            role="toolbar"
            aria-label="Selection actions"
            style={{ position: "absolute", left: layout.bar.left, top: layout.bar.top }}
          >
            {SELECTION_ACTIONS.map(({ label, hint }) => (
              <button key={label} type="button" className="cm-pz-selbar-btn" title={hint}>
                {label}
              </button>
            ))}
            <span className="cm-pz-selbar-status" role="status" hidden />
          </div>
        ) : null}
      </div>
    </div>
  );
}

