interface TreeRow {
  name: string;
  depth: number;
  /** A folder, open or closed; files carry their icon instead. */
  folder?: "open" | "closed";
  icon?: BrandIcon;
}

// The folder as FolderTree lists it (folders first, then files, by name),
// with src and src/routes opened to reach the file.
