// Go to file, Search in folder and Go to symbol (src/code/pickerBus.ts, CodePickers.tsx).
const PICKERS = [
  { icon: FileSearch, label: "Go to file", shortcut: "⌘P", keys: "Meta+P" },
  { icon: TextSearch, label: "Search in folder", shortcut: "⇧⌘F", keys: "Meta+Shift+F" },
  { icon: ListTree, label: "Go to symbol", shortcut: "⇧⌘O", keys: "Meta+Shift+O" },
];

/** TileCodePanel with a folder open and notes.ts in the editor, side by side with the terminal. */
function TileCodePanel() {
  const fileName = PATH.split("/").pop();
  return (
    <div className="tile-code">
      <div className="tile-code-bar">
        <button type="button" className="tile-btn tile-btn-on" title="Hide tree">
          <PanelLeft size={13} />
        </button>
        <div className="code-file-tab" title={PATH}>
          <span className="tile-code-name">{fileName}</span>
          <button type="button" className="tile-btn code-file-tab-close" title="Close file" aria-label="Close file">
            <X size={12} />
          </button>
        </div>
        <div className="tile-head-spacer" />
        {/* InlineBlameToggle: shown once the editor is wider than 520px; on by default. */}
        <span hidden />
        <button
          type="button"
          className="tile-btn tile-btn-on"
          title="Inline blame is on: the cursor line shows its last commit. Click to hide it."
          aria-label="Inline blame"
          aria-pressed
        >
          <GitCommitHorizontal size={13} />
        </button>
        {PICKERS.map(({ icon: Icon, label, shortcut, keys }) => (
          <button key={label} type="button" className="tile-btn code-picker-btn" title={`${label} (${shortcut})`} aria-label={label} aria-keyshortcuts={keys}>
            <Icon size={13} aria-hidden="true" />
          </button>
        ))}
        {/* CodeLayoutButtons, side by side. */}
        <button type="button" className="tile-btn" title="Side by side: switch to stacked" aria-label="Side by side: switch to stacked">
          <Columns2 size={13} />
        </button>
        <button type="button" className="tile-btn" title="Full editor" aria-label="Full editor" aria-pressed={false}>
          <Maximize2 size={13} />
        </button>
        <button type="button" className="tile-btn" title="Close editor" aria-label="Close editor">
          <X size={13} />
        </button>
      </div>
      <div className="code-split">
        <SidePanel />
        <div
          role="separator"
          tabIndex={0}
          aria-label="Resize file tree"
          aria-orientation="vertical"
          className="split-handle split-handle-x code-tree-handle"
        />
        <div className="code-editor-pane">
          <CodeEditor />
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------- shot -- */

// A 1440 x 900 window with the api session as its only tile, the editor open
// beside its terminal. The card frames the window's top-right corner on the
// editor, and no edge cuts a line of text: the left edge runs down the
// divider between the terminal and the editor, through the 2px gap between
// the top bar's All and fieldnotes workspace tabs (x 612..614), and the
// bottom edge falls between two of the file's lines (CodeMirror's 17.5px
// lines start at y 125, so line 33 ends at 702.5). The split, dragged to 43%,
// puts the editor's left border at x 614; the terminal, 603px wide there,
// runs the 65 column capture that fits it.
const TILE_BODY = { left: 11, width: 1418 };
const EDITOR_X = 614;
const SPLIT = (EDITOR_X - TILE_BODY.left) / TILE_BODY.width;
// The card starts 1px left of the editor and keeps 16px of wallpaper right of the window, 24px above it.
const BOX: Box = { left: -(EDITOR_X - 1), top: 24, ...WIN_SIZE };
const FRAME = { width: WIN_SIZE.width + 16 + BOX.left, height: BOX.top + 702 };

export function EditorShot() {
  const body = { position: "absolute", inset: 0, "--code-split": `${SPLIT * 100}%` } as CSSProperties;
  return (
    <Shot id="agents" width={FRAME.width} height={FRAME.height} className="editor-scene">
      <AppWindow box={BOX}>
        <ActiveCanvas
          style={{ gridTemplateColumns: "1fr", gridTemplateRows: "1fr" }}
          tiles={[
            <Tile
              key="api"
              title="api"
              agent="claude"
              kbd="⌘1"
              device={THIS_MAC}
              codeOpen
              strip={{ session: "api", branch: "main", path: SESSIONS.api.path, started: SESSIONS.api.started }}
            >
              {/* The app's tile body with the editor open (Canvas.tsx): the
                  terminal surface, the code panel and the split handle. Tile
                  keeps its own body box, so this fills it. */}
              <div className="tile-body tile-body-code-side-by-side" style={body}>
                <div className="term-surface">
                  <Term>
                    <AnsiScreen id="api-65" />
                  </Term>
                </div>
                <TileCodePanel />
                <div
                  role="separator"
                  tabIndex={0}
                  aria-label="Resize terminal and editor"
                  aria-orientation="vertical"
                  aria-valuenow={Math.round(SPLIT * 100)}
                  aria-valuemin={15}
                  aria-valuemax={85}
                  className="split-handle split-handle-x code-split-handle"
                />
              </div>
            </Tile>,
          ]}
        />
      </AppWindow>
    </Shot>
  );
}
